import{_ as a,o as i,c as s,ag as e}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"MSWaitSync 等待同步信号","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/21. 主从运动指令/MSWaitSync.md","filePath":"3. 指令/21. 主从运动指令/MSWaitSync.md","lastUpdated":1778862643000}'),d={name:"3. 指令/21. 主从运动指令/MSWaitSync.md"};function r(l,t,n,o,p,h){return i(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="mswaitsync-等待同步信号" tabindex="-1">MSWaitSync 等待同步信号 <a class="header-anchor" href="#mswaitsync-等待同步信号" aria-label="Permalink to &quot;MSWaitSync 等待同步信号&quot;">​</a></h1><p>该指令用于在指定时长内等待与本机器人协同运动的其他机器人反馈的协同准备信号。在设定时长内若等待条件满足，程序继续向下执行；若设定时长内条件未满足，则超时判断值置为 1 后，程序继续向下执行。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MSWaitSync([MSGroup], SyncId, T, Ret, [Goto])</p><p>MSWaitSync([主从组], 协同标识, 时长, 超时判断值, [超时跳转标签])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>[MSGroup]</td><td>enum</td><td>机器人协同运动时的主从组参数，用于在多机协同过程中区分所启用的机器人协同方式。详见下方 MSGroup 取值说明。</td><td>DEFAULT（仅限从机器人选择）</td></tr><tr><td>SyncId</td><td>SYNCID 变量</td><td>机器人协同标识 ID 号，用于本机与协同机器人之间进行协同校验，主从机器人 ID 一致时才为有效协同。</td><td></td></tr><tr><td>T</td><td>int 或 INT 变量</td><td>等待协同机器人反馈的协同准备信号的时长，单位 ms。值为 0 时强制等待直到条件满足。</td><td></td></tr><tr><td>Ret</td><td>INT 变量</td><td>返回该指令执行结束后的状态。0：成功检测到信号；1：未检测到信号，指令超时返回。</td><td></td></tr><tr><td>[Goto]</td><td>label</td><td>超时后跳转的 label 名，该 label 为在当前加载的程序中示教过的 label 指令名。</td><td>不跳转</td></tr></tbody></table><blockquote><p><strong>MSGroup 取值说明</strong>：</p><ul><li>MSGroup1：第一组主从组参数，仅限主机器人选择</li><li>MSGroup2：第二组主从组参数，仅限主机器人选择</li><li>MSGroup3：第三组主从组参数，仅限主机器人选择</li><li>MSGroup4：第四组主从组参数，仅限主机器人选择</li><li>MSGroup5：第五组主从组参数，仅限主机器人选择</li><li>MSGroup6：第六组主从组参数，仅限主机器人选择</li><li>MSGroup7：第七组主从组参数，仅限主机器人选择</li><li>DEFAULT：缺省类型，仅限从机器人选择</li></ul></blockquote><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MSWaitSync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MSGroup1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, SyncId1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT1, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Goto Start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析</strong>：</p><p>在 1000ms 时长内主机器人等待与之协同的从机器人的协同准备信号。若 1000ms 内成功等到该信号，程序继续向下执行；若 1000ms 内未等到条件满足，则将 INT1 置 1，同时程序指针将跳转到 &quot;Start&quot; 标签所在行（第一行）开始执行。</p>',14)])])}const S=a(d,[["render",r]]);export{u as __pageData,S as default};
